def encode_amount(dollars: str) -> str:
    # Parse the input string to validate format and extract components
    s = dollars.strip()
    if not s:
        raise ValueError("empty amount string")

    # Handle sign
    sign = ""
    if s[0] == "-":
        sign = "-"
        s = s[1:]
    elif s[0] == "+":
        s = s[1:]

    # Split into integer and fractional parts
    if "." not in s:
        integer_part = s
        fractional_part = "00"
    else:
        integer_part, fractional_part = s.split(".", 1)

    # Validate fractional part length
    if len(fractional_part) != 2:
        raise ValueError("amount must have exactly 2 decimal places")

    # Validate all characters are digits
    if not integer_part.isdigit() and integer_part != "":
        raise ValueError("invalid integer part")
    if integer_part == "" and not fractional_part:
        raise ValueError("invalid amount")
    if not fractional_part.isdigit():
        raise ValueError("invalid fractional part")

    # Handle empty integer part (e.g., ".50" -> "0.50")
    if integer_part == "":
        integer_part = "0"

    # Remove leading zeros from integer part (but keep at least one digit)
    integer_part = integer_part.lstrip("0") or "0"

    # Build the result: sign + integer_part + fractional_part (as integer string)
    # The wire format likely wants the value in cents as an integer string
    # e.g., "12.30" -> "1230", "-0.07" -> "-7"

    # Combine integer and fractional parts into cents
    combined = integer_part + fractional_part

    # Convert to integer to remove leading zeros, then back to string
    # But preserve the sign
    if sign == "-":
        # For negative, we want the minimal representation
        value = int(combined)
        return "-" + str(value)
    else:
        value = int(combined)
        return str(value)

