    # Validate format: optional negative sign, then digits, then optional decimal part
    if not isinstance(dollars, str):
        raise ValueError("dollars must be a string")

    s = dollars.strip()
    if not s:
        raise ValueError("empty string")

    # Check for negative
    negative = False
    if s[0] == '-':
        negative = True
        s = s[1:]
    elif s[0] == '+':
        s = s[1:]

    if not s:
        raise ValueError("no digits after sign")

    # Split integer and fractional parts
    if '.' in s:
        int_part, frac_part = s.split('.', 1)
        if not frac_part:
            frac_part = ""
    else:
        int_part, frac_part = s, ""

    if not int_part:
        raise ValueError("no integer part")

    # Validate integer part is all digits
    if not int_part.isdigit():
        raise ValueError(f"invalid integer part: {int_part}")

    # Validate fractional part is at most 2 digits and all digits (if present)
    if len(frac_part) > 2:
        raise ValueError("fractional part too long")
    if frac_part and not frac_part.isdigit():
        raise ValueError(f"invalid fractional part: {frac_part}")

    # Pad fractional part to 2 digits
    frac_part = frac_part.ljust(2, '0')

    # Remove leading zeros from integer part, but keep at least one digit
    int_part = int_part.lstrip('0') or '0'

    # Combine
    result = f"{int_part}.{frac_part}"
    if negative:
        result = f"-{result}"

    return result

